    public void handleOrders(Client client, Map<String, Object> message)
    {
        //
        //     {
        //         "topic": "sor",
        //         "args": [
        //             {
        //                 "acct": "U1234567",
        //                 "conid": 265598,
        //                 "orderId": 1234568790,
        //                 "orderType": "Limit",
        //                 "side": "BUY",
        //                 "price": "185.50",
        //                 "status": "Submitted",
        //                 "filledQuantity": 0.0,
        //                 "remainingQuantity": 5.0,
        //                 "totalSize": 5.0,
        //                 "timeInForce": "CLOSE",
        //                 "lastExecutionTime_r": 1702317649000,
        //                 "order_ref": "my-id"
        //             }
        //         ]
        //     }
        //
        List<Object> args = this.safeList(message, "args", new ArrayList<Object>(Arrays.asList()));
        Integer argsLength = args.size();
        if (java.util.Objects.equals(argsLength, 0))
        {
            return;
        }
        if (java.util.Objects.equals(this.orders, null))
        {
            Long limit = this.safeInteger(this.options, "ordersLimit", 1000);
            this.orders = new ArrayCache.ArrayCacheBySymbolById(((Number)limit).intValue());
        }
        io.github.ccxt.ws.ArrayCache orders = (io.github.ccxt.ws.ArrayCache) this.orders;
        // the updates are partial, e.g. { "acct": "U1234567", "orderId": 1911471157, "status": "Cancelled" } without the conid,
        // they are merged into the previous raw order of the same orderId
        Map<String, Object> subscription = this.safeDict(client.subscriptions, "sor", null);
        Map<String, Object> rawOrders = this.safeDict(subscription, "rawOrders", new HashMap<String, Object>() {{}});
        Map<String, Object> symbols = new HashMap<String, Object>() {{}};
        for (var i = 0; i < args.size(); i++)
        {
            Object rawOrder = (args == null || i < 0 || i >= args.size() ? null : args.get(i));
            String orderId = this.safeString(rawOrder, "orderId");
            Object merged = rawOrder;
            if (!java.util.Objects.equals(orderId, null))
            {
                Map<String, Object> previous = this.safeDict(rawOrders, orderId, new HashMap<String, Object>() {{}});
                merged = this.extend(previous, rawOrder);
                rawOrders.put(orderId, merged);
            }
            Map<String, Object> parsed = (Map<String, Object>) this.parseOrder(this.extend(new HashMap<String, Object>() {{}}, merged), null);
            orders.append(parsed);
            String orderSymbol = this.safeString(parsed, "symbol");
            if (!java.util.Objects.equals(orderSymbol, null))
            {
                symbols.put(orderSymbol, true);
            }
        }
        if (!java.util.Objects.equals(subscription, null))
        {
            subscription.put("rawOrders", rawOrders);
            client.subscriptions.put("sor", subscription);
        }
        client.resolve(orders, "orders");
        List<Object> keys = new ArrayList<Object>(symbols.keySet());
        for (var i = 0; i < keys.size(); i++)
        {
            client.resolve(orders, ("orders::" + (keys == null || i < 0 || i >= keys.size() ? null : keys.get(i))));
        }
    }

